import 'package:flutter/material.dart';import'../api/gaon_api.dart';class SmartCartAssist extends StatefulWidget{final Future<void>Function() onChanged;const SmartCartAssist({super.key,required this.onChanged});@override State<SmartCartAssist>createState()=>_State();}class _State extends State<SmartCartAssist>{List<dynamic>items=[];bool loading=true;@override void initState(){super.initState();load();}Future<void>load()async{try{final r=await GaonApi.basketRecommendations();if(mounted)setState((){items=List<dynamic>.from(r['items']??[]);loading=false;});}catch(_){if(mounted)setState(()=>loading=false);}}Future<void>add(String id)async{await GaonApi.addToCart(id);await widget.onChanged();await load();} @override Widget build(BuildContext context){if(loading)return const LinearProgressIndicator();if(items.isEmpty)return const SizedBox.shrink();return Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Complete your basket',style:Theme.of(context).textTheme.titleMedium?.copyWith(fontWeight:FontWeight.w700)),const Text('In-stock suggestions from the same store.'),...items.take(4).map((x)=>ListTile(contentPadding:EdgeInsets.zero,title:Text('${x['name']}'),subtitle:Text('${x['unit']} • ₹${x['price']}'),trailing:TextButton(onPressed:()=>add('${x['listing_id']}'),child:const Text('+ Add'))))])));}}
